{
  "items": [
    {
      "name": "geom_sum_alternating_of_le_neg_one",
      "module_name": "Mathlib.Algebra.Order.Ring.GeomSum",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Ring R] [inst_1 : PartialOrder R] [IsOrderedRing R] {x : R},\n  x + 1 ≤ 0 → ∀ (n : ℕ), if Even n then ∑ i ∈ Finset.range n, x ^ i ≤ 0 else 1 ≤ ∑ i ∈ Finset.range n, x ^ i"
    },
    {
      "name": "geom_sum_lt",
      "module_name": "Mathlib.Algebra.Order.Field.GeomSum",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Semifield K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] [CanonicallyOrderedAdd K]\n  [inst_4 : Sub K] [OrderedSub K] {x : K}, x ≠ 0 → x < 1 → ∀ (n : ℕ), ∑ i ∈ Finset.range n, x ^ i < (1 - x)⁻¹"
    },
    {
      "name": "pow_add_mul_le_add_pow",
      "module_name": "Mathlib.Algebra.Order.Ring.Pow",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] [inst_1 : LinearOrder R] [IsOrderedRing R] [ExistsAddOfLE R] {a b : R},\n  0 ≤ a → 0 ≤ 2 * a + b → ∀ (n : ℕ), a ^ n + ↑n * a ^ (n - 1) * b ≤ (a + b) ^ n"
    },
    {
      "name": "add_pow_le",
      "module_name": "Mathlib.Algebra.Order.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} [inst : Semiring R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] {a b : R} [ExistsAddOfLE R],\n  0 ≤ a → 0 ≤ b → ∀ (n : ℕ), (a + b) ^ n ≤ 2 ^ (n - 1) * (a ^ n + b ^ n)"
    },
    {
      "name": "geom_sum_Ico_le_of_lt_one",
      "module_name": "Mathlib.Algebra.Order.Field.GeomSum",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] {x : K} {m n : ℕ},\n  0 ≤ x → x < 1 → ∑ i ∈ Finset.Ico m n, x ^ i ≤ x ^ m / (1 - x)"
    },
    {
      "name": "pow_add_mul_le_add_pow_of_sq_nonneg",
      "module_name": "Mathlib.Algebra.Order.Ring.Pow",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] [inst_1 : PartialOrder R] [IsOrderedRing R] {a b : R},\n  0 ≤ a → 0 ≤ b ^ 2 → 0 ≤ (a + b) ^ 2 → 0 ≤ 2 * a + b → ∀ (n : ℕ), a ^ n + ↑n * a ^ (n - 1) * b ≤ (a + b) ^ n"
    },
    {
      "name": "geom_sum_pos",
      "module_name": "Mathlib.Algebra.Order.Ring.GeomSum",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] [inst_1 : PartialOrder R] [IsStrictOrderedRing R] {n : ℕ} {x : R},\n  0 ≤ x → n ≠ 0 → 0 < ∑ i ∈ Finset.range n, x ^ i"
    }
  ]
}
